import {renderScopeForm,editScopeDraft} from './scope-form.mjs';
import {archiveExecution} from './review-core.mjs';
import {reproductionState} from './reproduction-core.mjs';
import {bundleMatchesProject} from './material-intake.mjs';
export class ScopeReview {
 constructor(parent){this.parent=parent;this.i=parent.i;this.drafts=new Map();this.busy=false;}
 draft(p,b){const key=p.id+':'+b.active_plan_sha256;if(!this.drafts.has(key))this.drafts.set(key,{reviewer:'',json:JSON.stringify(b.review,null,2)});return this.drafts.get(key);}
 render(p,b){if(b.status!=='bound'||!b.review)return '';const d=this.draft(p,b),e=x=>this.i.esc(x);return `<details class="scope-review-editor"><summary>审核整篇实验清单、主要结论与方法对应</summary><p>对照全部论文页面与代码后记录具名审核。保存生成新的计划版本，保留原计划和文件指纹；不会修改代码、数据、命令或指标。引用与核心实验覆盖仍由服务器重新核对。</p><div class="field"><label for="scope-reviewer">审核人</label><input id="scope-reviewer" data-scope-reviewer value="${e(d.reviewer)}" ${this.busy?'disabled':''}></div>${renderScopeForm(d,e)}<details class="scope-advanced"><summary>高级 JSON · 排除项与完整声明</summary><div class="field"><label for="scope-review-json">实验清单与审核声明 JSON</label><textarea id="scope-review-json" data-scope-review-json rows="16" spellcheck="false" ${this.busy?'disabled':''}>${e(d.json)}</textarea></div></details><p class="small-note">experiments：实验 ID、labels、page、quote、core、conclusion_ids；conclusions：主要结论与原文引用。inventory_review.complete 和 method_review.verified 只在实际审核后确认，并填写 notes / source，以及 citations 中的 page / quote / paths 原文与代码映射。排除图表时在 excluded_references 写明原因。</p><button class="btn" data-scope-review-save ${this.busy||this.i.h.mode()!=='runtime'?'disabled':''}>${this.busy?'正在保存并重新核验…':'保存审核新版本并核验'}</button></details>`;}
 bind(){this.bindForm();document.addEventListener('input',event=>{if(!event.target.matches('[data-scope-reviewer],[data-scope-review-json]'))return;const p=this.i.current(),b=reproductionState(p).material_bundle;if(!b?.review)return;const d=this.draft(p,b);d[event.target.hasAttribute('data-scope-reviewer')?'reviewer':'json']=event.target.value;});document.addEventListener('click',async event=>{if(!event.target.closest('[data-scope-review-save]'))return;const p=this.i.current(),s=reproductionState(p),b=s.material_bundle,d=this.draft(p,b);this.parent.error='';try{if(this.i.h.mode()!=='runtime')throw Error('审核只写入本地工作台，托管预览不接收材料');if(s.bundle_stale||!bundleMatchesProject(b,p))throw Error('项目材料已变更，请先重新导入绑定');if(!d.reviewer.trim())throw Error('填写实际审核人');if(d.json.length>200000)throw Error('审核 JSON 最大 200,000 字符');const review=JSON.parse(d.json);this.busy=true;archiveExecution(s,'审核产生新的计划版本');s.audit=null;s.stale=true;this.i.h.render();const updated=await this.i.h.request('/api/materials/'+b.id+'/review',{reviewer:d.reviewer,review,parent_plan_sha256:b.active_plan_sha256});if(!bundleMatchesProject(updated,p)||s.bundle_stale||s.material_bundle.id!==b.id)throw Error('审核期间项目材料变化，需要重新核验');s.material_bundle=updated;s.plan_path=updated.plan_path;s.audit=await this.i.h.request('/api/reproduction/audit',{plan_path:s.plan_path,project_id:p.id,paper_sha256:p.paper.sha256,archive_sha256:p.repository.sha256,material_bundle_id:updated.id});if(!bundleMatchesProject(updated,p)||s.bundle_stale){s.audit=null;throw Error('材料发生变化，需要重新核验');}s.stale=false;await this.i.save(p);}catch(error){this.parent.error=error.message;}finally{this.busy=false;this.i.h.render();}});}
 bindForm(){document.addEventListener('input',event=>{const el=event.target;if(!el.dataset.scopePath)return;const p=this.i.current(),b=reproductionState(p).material_bundle,d=this.draft(p,b);try{editScopeDraft(d,el.dataset.scopePath,el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value);const raw=document.querySelector('[data-scope-review-json]');if(raw)raw.value=d.json;}catch(error){this.parent.error=error.message;}});document.addEventListener('click',event=>{const el=event.target.closest('[data-scope-add],[data-scope-remove]');if(!el)return;const p=this.i.current(),b=reproductionState(p).material_bundle,d=this.draft(p,b);try{const r=JSON.parse(d.json);r.paper??={};r.repository??={};r.repository.method_review??={};if(el.dataset.scopeAdd){const kind=el.dataset.scopeAdd;if(kind==='experiments')(r.paper.experiments??=[]).push({id:'',labels:[],page:1,quote:'',core:true,conclusion_ids:[]});if(kind==='conclusions')(r.paper.conclusions??=[]).push({id:'',text:'',page:1,quote:''});if(kind==='citations')(r.repository.method_review.citations??=[]).push({page:1,quote:'',paths:[]});}else{const [path,index]=el.dataset.scopeRemove.split(':');let rows=r;for(const k of path.split('.'))rows=rows[k];rows.splice(Number(index),1);}d.json=JSON.stringify(r,null,2);}catch(error){this.parent.error=error.message;}this.i.h.render();});}

}
